function groupStrings(words) {
  const parent = words.map((_, i) => i);
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  const union = (a, b) => {
    parent[find(a)] = find(b);
  };
  const masks = words.map((word) => {
    let mask = 0;
    for (const ch of word) {
      mask |= 1 << (ch.charCodeAt(0) - 97);
    }
    return mask;
  });
  const owner = new Map();
  for (let i = 0; i < masks.length; i++) {
    owner.set(masks[i], i);
  }
  const hub = new Map();
  for (let i = 0; i < masks.length; i++) {
    union(i, owner.get(masks[i]));
    for (let bit = 0; bit < 26; bit++) {
      if ((masks[i] & (1 << bit)) === 0) {
        continue;
      }
      const smaller = masks[i] ^ (1 << bit);
      if (owner.has(smaller)) {
        union(i, owner.get(smaller));
      }
      if (hub.has(smaller)) {
        union(i, hub.get(smaller));
      } else {
        hub.set(smaller, i);
      }
    }
  }
  const groupSize = new Map();
  for (let i = 0; i < words.length; i++) {
    const root = find(i);
    groupSize.set(root, (groupSize.get(root) || 0) + 1);
  }
  return [groupSize.size, Math.max(...groupSize.values())];
}

