function groupStrings(words) {
  const sets = words.map(w => new Set(w.split('')));
  const linked = (x, y) => {
    let onlyX = 0, onlyY = 0;
    for (const c of x) if (!y.has(c)) onlyX++;
    for (const c of y) if (!x.has(c)) onlyY++;
    return onlyX + onlyY <= 1 || (onlyX === 1 && onlyY === 1);
  };
  const n = words.length;
  const seen = new Array(n).fill(false);
  let groups = 0, largest = 0;
  for (let s = 0; s < n; s++) {
    if (seen[s]) continue;
    groups++;
    seen[s] = true;
    const stack = [s];
    let count = 0;
    while (stack.length) {
      const u = stack.pop();
      count++;
      for (let v = 0; v < n; v++) {
        if (!seen[v] && linked(sets[u], sets[v])) { seen[v] = true; stack.push(v); }
      }
    }
    largest = Math.max(largest, count);
  }
  return [groups, largest];
}

