function generate(rand, size) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const pick = (pool, length) => {
    const letters = pool.split('');
    for (let i = letters.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [letters[i], letters[j]] = [letters[j], letters[i]];
    }
    return letters.slice(0, length).join('');
  };
  if (size === 'large') {
    const poolSize = 6 + Math.floor(rand() * 21);
    const maxLength = 1 + Math.floor(rand() * Math.min(poolSize, 8));
    const pool = pick(alphabet, poolSize);
    const words = [];
    for (let i = 0; i < 2000; i++) {
      if (rand() < 0.3) words.push(pick(alphabet, 1 + Math.floor(rand() * 26)));
      else words.push(pick(pool, 1 + Math.floor(rand() * maxLength)));
    }
    return [words];
  }
  const n = 1 + Math.floor(rand() * 8);
  const pool = rand() < 0.6 ? 'abcde' : 'abcdefghij';
  const words = [];
  for (let i = 0; i < n; i++) words.push(pick(pool, 1 + Math.floor(rand() * 4)));
  return [words];
}
